from datetime import datetime, timedelta
from pathlib import Path

BASE = Path('/app')
PEOPLE = {
    'alice': {'email': 'alice@example.com', 'file': 'alice_calendar.ics'},
    'bob': {'email': 'bob@example.com', 'file': 'bob_calendar.ics'},
    'carol': {'email': 'carol@example.com', 'file': 'carol_calendar.ics'},
}
FMT = '%Y%m%dT%H%M%SZ'


def parse_ics(path):
    events = []
    cur = None
    for raw in path.read_text().splitlines():
        line = raw.strip()
        if line == 'BEGIN:VEVENT':
            cur = {}
        elif line == 'END:VEVENT':
            if cur and 'DTSTART' in cur and 'DTEND' in cur:
                events.append((
                    datetime.strptime(cur['DTSTART'], FMT),
                    datetime.strptime(cur['DTEND'], FMT),
                    cur.get('SUMMARY', ''),
                ))
            cur = None
        elif cur is not None and ':' in line:
            key, value = line.split(':', 1)
            key = key.split(';', 1)[0]
            if key in ('DTSTART', 'DTEND', 'SUMMARY'):
                cur[key] = value
    return events


def at(day, hour, minute=0):
    return datetime(day.year, day.month, day.day, hour, minute)


def hard_windows(person, day):
    """Half-open [start, end) windows when the person may meet."""
    if day.weekday() >= 5:
        return []
    if person == 'alice':
        return [(at(day, 9), at(day, 14))]
    if person == 'bob':
        start = at(day, 10)
        end = at(day, 16, 30) if day.weekday() in (1, 3) else at(day, 18)
        return [(start, end)]
    if person == 'carol':
        return [(at(day, 9), at(day, 12)), (at(day, 12, 30), at(day, 17))]
    raise ValueError(person)


def inside_window(start, end, window):
    return start >= window[0] and end <= window[1]


def overlaps(start, end, busy_start, busy_end):
    return start < busy_end and end > busy_start


calendars = {p: parse_ics(BASE / info['file']) for p, info in PEOPLE.items()}

# Build the first valid 1-hour slot, scanning days and then minutes.
start_day = datetime(2024, 1, 15)
chosen = None
for day_offset in range(5):
    day = start_day + timedelta(days=day_offset)
    if day.weekday() >= 5:
        continue
    cursor = at(day, 9)
    day_end = at(day, 18)
    while cursor + timedelta(hours=1) <= day_end:
        end = cursor + timedelta(hours=1)
        valid = True
        for person in PEOPLE:
            if not any(inside_window(cursor, end, w) for w in hard_windows(person, day)):
                valid = False
                break
            for busy_start, busy_end, _ in calendars[person]:
                # Carol requires 15 minutes after meetings ending at/after 16:45.
                if person == 'carol' and busy_start.date() == day.date() and busy_end.hour * 60 + busy_end.minute >= 16 * 60 + 45:
                    busy_end = busy_end + timedelta(minutes=15)
                if overlaps(cursor, end, busy_start, busy_end):
                    valid = False
                    break
            if not valid:
                break
        if valid:
            chosen = (cursor, end)
            break
        cursor += timedelta(minutes=1)
    if chosen:
        break

if chosen is None:
    raise SystemExit('No valid meeting slot found')

start, end = chosen
print(f'Chosen slot: {start.isoformat()} - {end.isoformat()}')

ics = f"""BEGIN:VCALENDAR
VERSION:2.0
PRODID:-//Terminal-Bench//Meeting Scheduler//EN
CALSCALE:GREGORIAN
METHOD:PUBLISH
BEGIN:VEVENT
UID:team-planning-meeting-{start.strftime(FMT)}@example.com
DTSTAMP:{start.strftime(FMT)}
DTSTART:{start.strftime(FMT)}
DTEND:{end.strftime(FMT)}
