ATTENDEE;CN=Carol;ROLE=REQ-PARTICIPANT:mailto:carol@example.com
END:VEVENT
END:VCALENDAR
"""
(BASE / 'meeting_scheduled.ics').write_text(ics)
print('Wrote /app/meeting_scheduled.ics')
